vulnerabilities.fix:
Before:
$logPath = rtrim($_SERVER['DOCUMENT_ROOT'] ?? '', '/\\') . '/' . ltrim($logPath, '/\\');

After:
$logPath = rtrim($_SERVER['DOCUMENT_ROOT'] ?? '', '/\\') . '/' . ltrim($logPath, '/\\');
$docRoot = rtrim($_SERVER['DOCUMENT_ROOT'] ?? '', '/\\');
$realBase = str_replace('\\', '/', realpath($docRoot));
$realDir = str_replace('\\', '/', realpath(dirname($logPath)));
if ($realDir !== false && $realBase !== false && strpos($realDir, $realBase) === 0) {
    // путь внутри document_root: отказ или перевод в защищённый каталог
    return;
}
